import{esc,toast}from './ui.js';
import{read,write}from './storage.js';
import{NATIVE_BOOK_ID,NATIVE_UNIT_IDS,normalizeNativeProgress}from './owner-native-progress.js';
const home='#knowledge?preview=muallim',href=id=>home+(id?'&unit='+id:'');
const key='muallim-native-progress';
const ar=t=>'<span class="alphabet-glyph native-ar" lang="ar" dir="rtl">'+esc(t)+'</span>';
const sample=t=>/[\u0600-\u06ff]/.test(t)?ar(t):esc(t);
export function showNativeMuallim(host,options={}){
 if(options.curriculum)return mountNativeMuallim(host,options);
 let alive=true,stop=null;host.innerHTML='<section class="alphabet-page native-course"><h1>Муаллим Сани</h1><p role="status">Открываем занятия…</p></section>';
 Promise.resolve().then(()=>options.loadCurriculum?.()).then(curriculum=>{if(alive)stop=mountNativeMuallim(host,{...options,curriculum});}).catch(()=>{if(alive)host.innerHTML='<section class="alphabet-page native-course"><a class="alphabet-back" href="#knowledge">← Знания</a><h1>Курс пока недоступен</h1><p role="alert">Проверьте соединение и подтверждение входа владельца.</p></section>';});
 return()=>{alive=false;stop?.();};
}
function mountNativeMuallim(host,{hash=location.hash,hasBook=false,curriculum}={}){
 if(curriculum?.bookId!==NATIVE_BOOK_ID||!Array.isArray(curriculum.units)||curriculum.units.map(u=>u.id).join()!==NATIVE_UNIT_IDS.join()||!Array.isArray(curriculum.blocks))throw Error('Invalid course');
 const NATIVE_COURSE=curriculum.units,NATIVE_BLOCKS=curriculum.blocks,nativeUnit=id=>NATIVE_COURSE.find(u=>u.id===id)||null;
 const nativeQuiz=unit=>{const items=[...unit.questions];for(let i=items.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[items[i],items[j]]=[items[j],items[i]];}return items.slice(0,6);};
 let progress=normalizeNativeProgress(read(key,null)),tab='learn',quiz=null,disposed=false;
 const params=new URLSearchParams(hash.split('?')[1]||''),unit=nativeUnit(params.get('unit')||(params.get('homework')==='mim'?'letter-mim':null));
 const save=value=>{progress=value;if(!write(key,value))toast('Прогресс не удалось сохранить в SALAH.');};
 const focus=()=>{window.scrollTo({top:0,behavior:'instant'});host.querySelector('h1')?.focus({preventScroll:true});};
 const source=u=>hasBook?'<a class="native-source" href="'+home+'&bookPage='+u.page+'">Свериться с учебником · стр. '+u.page+' ↗</a>':'<span class="native-source">По учебнику · стр. '+u.page+'</span>';
 function hub(){
  const resume=nativeUnit(progress.last)||nativeUnit('letter-mim');
  host.innerHTML='<section class="alphabet-page muallim-page native-course"><a class="alphabet-back" href="#knowledge">← Знания</a><div class="native-course-kicker">ОБУЧЕНИЕ ЧТЕНИЮ · SALAH</div><h1 tabindex="-1">Муаллим Сани</h1><p class="native-lead">От первых букв к уверенному чтению. Короткие занятия по последовательности вашего учебника.</p><section class="native-resume"><span class="native-resume-glyph" lang="ar" dir="rtl" aria-hidden="true">'+esc(resume.glyph||'ا ب')+'</span><span class="native-label">ПРОДОЛЖИТЬ</span><h2>'+esc(resume.title)+'</h2><p>Разобраться · прочитать · проверить себя</p><a class="button" href="'+href(resume.id)+'">Открыть занятие →</a></section><a class="native-homework" href="'+href('letter-mim')+'"><span class="native-homework-glyph" lang="ar" dir="rtl">م</span><span><small>ДОМАШНЕЕ ЗАДАНИЕ</small><strong>Буква Мим</strong><span>Огласовки, слоги и 6 заданий</span></span><span aria-hidden="true">→</span></a><div class="native-progress"><div><span>Письменные проверки</span><strong>'+progress.completed.length+' / '+NATIVE_COURSE.length+'</strong></div><progress max="'+NATIVE_COURSE.length+'" value="'+progress.completed.length+'" aria-label="Пройденные письменные проверки"></progress></div><div class="native-blocks">'+NATIVE_BLOCKS.map((block,i)=>'<details class="native-block" '+(i===0?'open':'')+'><summary><span class="native-block-number">'+String(i+1).padStart(2,'0')+'</span><span><strong>'+esc(block.title)+'</strong><small>'+esc(block.detail)+'</small></span><span class="native-block-count">'+block.ids.filter(id=>progress.completed.includes(id)).length+' / '+block.ids.length+'</span></summary><ol class="native-unit-list">'+block.ids.map(id=>{const u=nativeUnit(id);return '<li><a href="'+href(id)+'"><span class="native-unit-symbol '+(u.glyph?'is-letter':'')+'" '+(u.glyph?'lang="ar" dir="rtl"':'')+'>'+esc(u.glyph||String(u.index+1))+'</span><span><strong>'+esc(u.title)+'</strong><small>'+esc(u.block==='letters'?'Буква · слоги · проверка':'Правило · примеры · проверка')+'</small></span><span class="native-unit-state">'+(progress.completed.includes(id)?'✓':'→')+'</span></a></li>';}).join('')+'</ol></details>').join('')+'</div><details class="native-about"><summary>Об учебном курсе</summary><p>Материал адаптирован для экранов SALAH по присланному учебнику. Это закрытая учебная версия для проверки с преподавателем. Автоматическая проверка относится к написанию и правилам; она не оценивает голос.</p><p>Аудиозаписи для всего курса пока не добавлены. Произношение и длительность повторяйте за преподавателем.</p>'+(hasBook?'<a class="native-source" href="'+home+'&source=1">Открыть оригинальные страницы учебника →</a>':'')+'<a class="native-source" href="'+home+'&practice=1">Дополнительный тренажёр основ →</a></details></section>';focus();
 }
 function shell(){
  host.innerHTML='<section class="alphabet-page muallim-page native-course native-lesson"><a class="alphabet-back" href="'+home+'">← Все занятия</a><div class="native-course-kicker">ЗАНЯТИЕ '+(unit.index+1)+' ИЗ '+NATIVE_COURSE.length+'</div><header class="native-lesson-head"><div><h1 tabindex="-1">'+esc(unit.title)+'</h1><p>'+esc(unit.goal)+'</p></div>'+(unit.glyph?'<span class="native-lesson-glyph" lang="ar" dir="rtl" aria-hidden="true">'+esc(unit.glyph)+'</span>':'')+'</header><div class="native-tabs" role="tablist" aria-label="Шаги занятия">'+[['learn','Разобраться'],['read','Читать'],['quiz','Проверка']].map(([id,title])=>'<button type="button" role="tab" id="native-tab-'+id+'" aria-controls="native-panel" data-tab="'+id+'" aria-selected="'+(tab===id)+'">'+title+'</button>').join('')+'</div><div id="native-panel" class="native-panel" role="tabpanel" aria-labelledby="native-tab-'+tab+'"></div>'+source(unit)+'<nav class="native-navigation" aria-label="Соседние занятия">'+(unit.index?'<a href="'+href(NATIVE_COURSE[unit.index-1].id)+'">← Назад</a>':'<a href="'+home+'">← К курсу</a>')+(unit.index<NATIVE_COURSE.length-1?'<a href="'+href(NATIVE_COURSE[unit.index+1].id)+'">Дальше →</a>':'<a href="'+home+'">К курсу →</a>')+'</nav></section>';
  host.querySelectorAll('[data-tab]').forEach(b=>{b.onclick=()=>selectTab(b.dataset.tab);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...host.querySelectorAll('[data-tab]')],i=tabs.indexOf(b),next=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;selectTab(tabs[next].dataset.tab);tabs[next].focus();};});drawPanel();
 }
 function selectTab(value){if(!['learn','read','quiz'].includes(value))return;tab=value;host.querySelectorAll('[data-tab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.tab===tab));b.tabIndex=b.dataset.tab===tab?0:-1;});const panel=host.querySelector('#native-panel');panel.setAttribute('aria-labelledby','native-tab-'+tab);drawPanel();}
 function drawPanel(){
  const panel=host.querySelector('#native-panel');
  if(tab==='learn'){
   panel.innerHTML='<h2>Разберёмся вместе</h2>'+unit.explanation.map((text,i)=>'<article class="native-explanation"><span>'+String(i+1).padStart(2,'0')+'</span><p>'+esc(text)+'</p></article>').join('')+(unit.forms?'<section class="native-forms"><h3>Узнаём в записи</h3><div>'+unit.forms.map(ar).join('')+'</div><p>Сравните отдельную букву и её соединения. Если буква не соединяется со следующей слева, это её особенность.</p></section>':'')+'<button type="button" class="button" data-to-reading>Перейти к чтению →</button>';panel.querySelector('[data-to-reading]').onclick=()=>selectTab('read');
  }else if(tab==='read'){
   panel.innerHTML='<h2>Читаем внимательно</h2><p>Начинайте справа. Учебные схемы с «+» показывают соседние буквы; их не читают как отдельное слово.</p>'+unit.rows.map((row,i)=>'<article class="native-reading-row"><div><span>'+String(i+1).padStart(2,'0')+'</span><h3>'+esc(row.title)+'</h3></div><p>'+esc(row.instruction)+'</p><div class="native-reading-cells" dir="rtl">'+row.tokens.map(ar).join('')+'</div></article>').join('')+'<section class="native-practice"><h3>Перед проверкой</h3><ul>'+unit.practice.map(text=>'<li>'+esc(text)+'</li>').join('')+'</ul></section><button type="button" class="button" data-to-quiz>Проверить себя →</button>';panel.querySelector('[data-to-quiz]').onclick=()=>selectTab('quiz');
  }else drawQuiz(panel);
 }
 function startQuiz(items=null){quiz={items:items||nativeQuiz(unit),index:0,answers:[],answered:false,review:items!==null,choiceOrder:null};drawQuiz(host.querySelector('#native-panel'));}
 function drawQuiz(panel){
  if(!quiz){panel.innerHTML='<h2>Проверим написание и правила</h2><p>Шесть заданий с объяснениями. Ошибки можно разобрать и пройти проверку ещё раз.</p><p class="native-note">Эта проверка не оценивает произношение. Прочитайте строки преподавателю.</p><button class="button" type="button" data-native-start>Начать проверку</button>';panel.querySelector('[data-native-start]').onclick=()=>startQuiz();return;}
  const item=quiz.items[quiz.index];
  if(!item){
   const errors=quiz.answers.filter(a=>!a.correct),passed=errors.length===0;
   if(passed&&!quiz.review&&quiz.items.length===6&&!progress.completed.includes(unit.id))save({...progress,completed:[...progress.completed,unit.id]});
   panel.innerHTML='<div class="native-result"><span class="native-label">'+(quiz.review?'ПОВТОРЕНИЕ':'РЕЗУЛЬТАТ')+'</span><h2>'+(passed?(quiz.review?'Ошибки разобраны':'Письменная проверка пройдена'):'Повторим сложное')+'</h2><p>Верных ответов: <strong>'+quiz.answers.filter(a=>a.correct).length+' из '+quiz.items.length+'</strong>.</p><p>'+(quiz.review?'Для отметки в курсе пройдите полную проверку из шести заданий.':'Прочитайте тему преподавателю: правильный выбор ответа не заменяет правильное произношение.')+'</p></div>'+errors.map(a=>'<article class="native-error"><h3>'+esc(a.item.prompt)+'</h3><p>Ваш ответ: '+sample(a.item.choices[a.chosen])+'</p><p>Верный ответ: '+sample(a.item.choices[a.item.answer])+'</p><p>'+esc(a.item.why)+'</p></article>').join('')+'<div class="native-result-actions">'+(errors.length?'<button class="button secondary" type="button" data-native-errors>Разобрать ошибки · '+errors.length+'</button>':'')+'<button class="button" type="button" data-native-repeat>Новая проверка</button><button class="button secondary" type="button" data-native-read>Вернуться к строкам</button></div>';
   panel.querySelector('[data-native-repeat]').onclick=()=>startQuiz();panel.querySelector('[data-native-read]').onclick=()=>selectTab('read');panel.querySelector('[data-native-errors]')?.addEventListener('click',()=>startQuiz(errors.map(a=>a.item)));return;
  }
  if(!quiz.choiceOrder){quiz.choiceOrder=item.choices.map((text,index)=>({text,index}));for(let i=quiz.choiceOrder.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[quiz.choiceOrder[i],quiz.choiceOrder[j]]=[quiz.choiceOrder[j],quiz.choiceOrder[i]];}}
  const answer=quiz.answers[quiz.index];
  panel.innerHTML='<div class="native-question" data-native-question="'+item.id+'"><span class="native-label">'+(quiz.review?'ПОВТОРЕНИЕ':'ЗАДАНИЕ')+' '+(quiz.index+1)+' / '+quiz.items.length+'</span><h2>'+esc(item.prompt)+'</h2><div class="native-choices">'+quiz.choiceOrder.map(c=>'<button type="button" data-native-answer="'+c.index+'" '+(quiz.answered?'disabled':'')+' class="'+(quiz.answered&&(c.index===item.answer||c.index===answer?.chosen)?(c.index===item.answer?'is-correct':'is-wrong'):'')+'">'+sample(c.text)+'</button>').join('')+'</div><p class="native-feedback" role="status">'+(quiz.answered?esc(item.why):'')+'</p><button class="button" type="button" data-native-next '+(!quiz.answered?'hidden':'')+'>'+(quiz.index===quiz.items.length-1?'Результат':'Далее →')+'</button></div>';
  panel.querySelectorAll('[data-native-answer]').forEach(button=>button.onclick=()=>{if(quiz.answered)return;const chosen=Number(button.dataset.nativeAnswer);quiz.answered=true;quiz.answers[quiz.index]={item,chosen,correct:chosen===item.answer};drawQuiz(panel);});
  panel.querySelector('[data-native-next]').onclick=()=>{if(!quiz.answered)return;quiz.index++;quiz.answered=false;quiz.choiceOrder=null;drawQuiz(panel);};
 }
 if(unit){if(progress.last!==unit.id)save({...progress,last:unit.id});shell();selectTab('learn');focus();}else hub();
 return()=>{disposed=true;quiz=null;};
}
